package com.tracker.controller;
import com.tracker.dto.AuthDtos.*; import com.tracker.service.*; import jakarta.validation.Valid; import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/users") public class UserController { private final AccessService access; private final AuthService auth; public UserController(AccessService a,AuthService s){access=a;auth=s;} @GetMapping("/me") public UserView me(Authentication a){return auth.view(access.current(a));} @PutMapping("/me") public UserView update(@Valid @RequestBody Profile p,Authentication a){var u=access.current(a);u.setName(p.name());u.setPhone(p.phone());u.setDepartment(p.department());u.setBranch(p.branch());u.setAcademicYear(p.academicYear());u.setInstitution(p.institution());u.setStudentId(p.studentId());u.setGraduationYear(p.graduationYear());u.setBiography(p.biography());u.setCareerInterests(p.careerInterests());u.setTargetCareerRole(p.targetCareerRole());u.setGithubUrl(p.githubUrl());u.setLinkedinUrl(p.linkedinUrl());u.setPortfolioUrl(p.portfolioUrl());u.setProfilePhotoUrl(p.profilePhotoUrl());u.setDesignation(p.designation());return auth.view(access.save(u));} }
